  const toggleCompare = (p) => {
    setCompareList(prev => {
      const exists = prev.find(x => x.id === p.id);
      if (exists) {
        notify("Removed " + p.name + " from comparison");
        return prev.filter(x => x.id !== p.id);
      }
      if (prev.length >= 3) {
        notify("⚠️ Max 3 projects for comparison");
        return prev;
      }
      notify("✅ Added " + p.name + " to comparison");
      return [...prev, p];
    });
  };

